def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    opp = [h[1] for h in history]
    my = [h[0] for h in history]
    opp_c = opp.count('C')
    opp_rate = opp_c / n
    last_opp = opp[-1]
    last_me = my[-1]
    my_d = my.count('D')

    if n >= 20 and opp_rate > 0.9 and my_d >= 2:
        return 'D'

    if n >= 10 and opp_rate < 0.3:
        return 'D'

    if last_opp == 'C':
        return 'C'
    else:
        if last_me == 'D':
            dd_streak = 0
            for i in range(n-1, -1, -1):
                if my[i] == 'D' and opp[i] == 'D':
                    dd_streak += 1
                else:
                    break
            if dd_streak >= 4:
                return 'C'
            return 'D'
        else:
            window = min(5, n)
            recent_c = sum(1 for a in opp[-window:] if a == 'C')
            if recent_c / window >= 0.3:
                return 'C'
            return 'D'
